import csv
OUTPUT='data/research_batches/detailed_verified_3001_batch_610.csv'; FIELDS='tlg_author_id tlg_work_id author_heading work_title canonical_edition sources_tested open_text_result open_text_url open_text_license scan_result scan_url scan_rights confidence proposed_status next_action notes last_checked'.split()
