with open(OUTPUT,'w',newline='',encoding='utf-8') as h:
 w=csv.DictWriter(h,fieldnames=FIELDS,lineterminator='\n');w.writeheader()
 for work in ['001','002','003','004','005']:
  s=canon[('0035',work)]; c=[r for r in matches if r['tlg_author_id']=='0035' and r['tlg_work_id']==work and r['corpus']=='Perseus']; v=[r for r in checks if r['tlg_author_id']=='0035' and r['tlg_work_id']==work and r['corpus']=='Perseus']; assert len(c)==len(v)==1 and v[0]['automated_check']=='AUTOMATED_TEI_CHECK_PASSED'; row={f:'' for f in FIELDS}
